import { expect, test, uniqueName } from "../../fixtures";

const cases = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

test.describe("manage vendors", () => {
  for (const { field, value } of cases) {
    test(`rejects a vendor with invalid ${field}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const payload: Record<string, string> = {
        name: uniqueName("Vendor"),
        category: "software",
        contact_email: "ops@example.test",
        [field]: value,
      };

      // Act
      const response = await member.post("/api/vendors", { data: payload });

      // Assert
      const body = await response.text();
      expect(response.status(), body).toBe(422);
      const error = JSON.parse(body).error;
      expect(error.code, body).toBe("validation_error");
      const fields = (error.fields as { field: string }[]).map((f) => f.field);
      expect(fields, body).toContain(field);
    });
  }
});
